def _m_sum_float(xs, w, m):
    return [sum(xs[i:i + w], 0.0) / w for i in range(m)]


def _m_sum_int(xs, w, m):
    return [sum(xs[i:i + w], 0) / w for i in range(m)]


def _m_sum_int_islice(xs, w, m):
    return [sum(_islice(xs, i, i + w), 0) / w for i in range(m)]


def _m_acc(xs, w, m):
    return [list(_accumulate(xs[i:i + w], initial=0.0))[-1] / w for i in range(m)]


def _m_reduce(xs, w, m):
    return [_reduce(_add, xs[i:i + w], 0.0) / w for i in range(m)]


def _m_mapvec(xs, w, m):
    partials = [0.0] * m
    for k in range(w):
        partials = list(map(_add, partials, xs[k:k + m]))
    return [p / w for p in partials]


def _m_array_sum_int(xs, w, m):
